INSERT INTO adj_factor (security_id,ex_date,factor,method,status) SELECT (SELECT security_id FROM security_identifier WHERE id_type='nse_symbol' AND value='HDFCNIFIT' ORDER BY valid_from DESC LIMIT 1), '2024-02-02', '0.1', 'manual', 'confirmed' WHERE (SELECT security_id FROM security_identifier WHERE id_type='nse_symbol' AND value='HDFCNIFIT' ORDER BY valid_from DESC LIMIT 1) IS NOT NULL ON CONFLICT (security_id,ex_date) DO UPDATE SET factor=excluded.factor, method='manual', status='confirmed';
